sys_script_fix.script:
var labelsA = [gs.getMessage('Discovered product'), gs.getMessage('Discovered publisher'), gs.getMessage('Discovered version')];
var columsA = ['display_name', 'publisher', 'version'];

for (var index = 0; index < labelsA.length; index++) {
	var dictGr = new GlideRecord('sys_dictionary');
	dictGr.addQuery('name', 'cmdb_sam_sw_discovery_model');
	dictGr.addQuery('element', columsA[index]);
	dictGr.addQuery('column_label', '!=', labelsA[index]);
	dictGr.query();

	if (dictGr.next()) {
		dictGr.setValue('column_label', labelsA[index]);
		dictGr.update();
	}
}
